function [t_stall, w_nl] = motor_constants(kt, r, v)
%MOTOR_CONSTANTS  The motor's stall torque [N m] and no-load speed [rad/s] from its torque constant k_t [N m/A], winding resistance r
%   [ohm] and the bus voltage v [V].
%   kt: real[1] (passed a plain number)
%   r: real[1] (passed a plain number)
%   v: real[1] (passed a plain number)
%   returns t_stall: real[1] (passed a plain number)
%   returns w_nl: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    t_stall = 0;
    w_nl = 0;
    t_stall = ((kt * v) / r);
    w_nl = (v / kt);
end
